import { Controller } from "@hotwired/stimulus"
import { signedDifferenceInDays, differenceInDays } from "helpers/date_helpers"

const REFRESH_INTERVAL = 3_600_000 // 1 hour (in milliseconds)

export default class extends Controller {
  static targets = [ "entropy", "top", "center", "bottom" ]
  static values = { entropy: Object }

  #timer

  connect() {
    this.#timer = setInterval(this.update.bind(this), REFRESH_INTERVAL)
    this.update()
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  update() {
    if (this.#isStalled) {
      this.#showStalled()
    } else if (this.#hasEntropy) {
      this.#showEntropy()
    } else {
      this.#hide()
    }
  }

  get #isStalled() {
    return Boolean(this.entropyValue.stalled)
  }

  get #hasEntropy() {
    return Boolean(this.entropyValue.daysBeforeReminder && this.#entropyCleanupInDays < this.entropyValue.daysBeforeReminder)
  }

  get #entropyCleanupInDays() {
    return this.entropyValue.closesAt ? signedDifferenceInDays(new Date(), new Date(this.entropyValue.closesAt)) : Infinity
  }

  get #stalledInDays() {
    if (this.entropyValue.stalledInDays != null) {
      return this.entropyValue.stalledInDays
    }
    return differenceInDays(new Date(this.entropyValue.lastActiveAt), new Date())
  }

  #showEntropy() {
    this.#render({
      top: this.#entropyCleanupInDays < 1 ? this.entropyValue.action : `${this.entropyValue.action} in`,
      center: this.#entropyCleanupInDays < 1 ? "!" : this.#entropyCleanupInDays,
      bottom: this.#entropyCleanupInDays < 1 ? "Today" : (this.#entropyCleanupInDays === 1 ? "day" : "days"),
    })
  }

  #render({ top, center, bottom }) {
    this.topTarget.innerHTML = top
    this.centerTarget.innerHTML = center
    this.bottomTarget.innerHTML = bottom

    this.#show()
  }

  #showStalled() {
    const days = this.#stalledInDays
    this.#render({
      top: "Stalled for",
      center: days,
      bottom: days === 1 ? "day" : "days"
    })
  }

  #hide() {
    this.element.toggleAttribute("hidden", true)
  }

